/// Makes every type's data known to the runtime (`o.GetType()` of an object, `Type.GetType(name)`,
/// `Activator.CreateInstance`).
pub fn register_all() {
    for m in ALL {
        rt::meta_register(m);
    }
    for (name, public, ctor) in CTORS {
        rt::ctor_register(name, *public, *ctor);
    }
}

